-- La etapa del plan de Chaumer. Fase 5b de docs/disenos/2026-09-24-etapa-plan-chaumer.md.
--
-- 1. `plan_bloque`: el bloque de la checklist (o la categoría del plan) de cada fila,
--    para enseñar el plan agrupado en Estrategia.
-- 2. Etapas: la 1 se cierra el 23/09 y la 2 (Plan de Chaumer) empieza el 24/09. Decisión
--    de Kris: el trade de hoy es el piloto. Las 17 casillas viejas del 24/09 se quedan en
--    la base y dejan de contar (un día es de una sola etapa).
-- 3. Las reglas del plan: SQL generado por scripts/plan/sincronizar.mjs (no editar a mano):
--    40 reglas, 48 líneas de la checklist diaria (2 casillas, 5 automáticas, 41 guía) y 2
--    automáticas que salen de reglas (R-02 ventana horaria, R-04 un contrato).
-- 4. Las 17 casillas de la etapa 1 pasan a activa = false: dejan de verse para marcar en el
--    Diario y en NinjaTrader, y SIGUEN contando en la etapa 1 (la disciplina mira `etapa`).

alter table catalogo_reglas add column if not exists plan_bloque text;
comment on column catalogo_reglas.plan_bloque is
  'Bloque de la checklist diaria del plan (o categoría de la regla) de donde sale la fila. Solo en origen plan_*.';

update disciplina_etapas set hasta = '2026-09-23' where id = 1;
   'El checklist sacado del plan de Chaumer (chaumer/01_Plan): 2 casillas y 7 automáticas.')
on conflict (id) do nothing;

on conflict (codigo) do update set
  titulo = excluded.titulo,
  enunciado = excluded.enunciado,
  capa = excluded.capa,
  tipo = excluded.tipo,
  fase = excluded.fase,
  setup = excluded.setup,
  es_checklist = excluded.es_checklist,
  orden = excluded.orden,
  evidencia = excluded.evidencia,
  bloquea_go = excluded.bloquea_go,
  aplica_si = excluded.aplica_si,
  plan_reglas = excluded.plan_reglas,
  origen = excluded.origen,
  plan_tipo = excluded.plan_tipo,
  plan_bloque = excluded.plan_bloque,
  campo = excluded.campo,
  estado = excluded.estado,
  activa = excluded.activa,
  etapa = excluded.etapa,
  updated_at = now();

-- Lo que ya no está en el plan se desactiva (nunca se borra: su historial sigue contando).
update catalogo_reglas set activa = false, updated_at = now()
 where etapa = 2 and origen in ('plan_linea', 'plan_regla') and activa
   and codigo not in ('R-01', 'R-02', 'R-03', 'R-04', 'R-05', 'R-06', 'R-07', 'R-08', 'R-09', 'R-10', 'R-11', 'R-12', 'R-13', 'R-14', 'R-15', 'R-16', 'R-17', 'R-18', 'R-19', 'R-20', 'R-21', 'R-22', 'R-23', 'R-24', 'R-25', 'R-26', 'R-27', 'R-40', 'R-41', 'R-28', 'R-29', 'R-30', 'R-31', 'R-32', 'R-33', 'R-34', 'R-35', 'R-36', 'R-37', 'R-38', 'p2_g_7ca8fa6a', 'p2_g_56e12136', 'p2_g_c2fe2169', 'p2_g_3c6db45c', 'p2_g_d5a65697', 'p2_g_954acdc6', 'p2_g_f322eb01', 'p2_g_bdc4380f', 'p2_g_88dfc66e', 'p2_g_ad8984a6', 'p2_g_05dcd39d', 'p2_g_32e3a881', 'p2_g_509ccd8b', 'p2_g_882c476d', 'p2_corrida_fluida', 'p2_g_3891b80b', 'p2_g_a82d169d', 'p2_g_fad99fde', 'p2_stop_max', 'p2_g_9e2b60e5', 'p2_punto_referencia', 'p2_g_0525f6f2', 'p2_fomc_continuacion', 'p2_noticia', 'p2_g_8a5d31d2', 'p2_instrumento', 'p2_g_c214cf46', 'p2_g_ed59f89a', 'p2_g_ed096ec1', 'p2_g_3e1b11b1', 'p2_g_ec38f419', 'p2_g_32941671', 'p2_g_ab1071ef', 'p2_g_c71bf461', 'p2_g_9963d984', 'p2_g_218eb551', 'p2_una_operacion', 'p2_g_47bfb2ed', 'p2_g_411dcd27', 'p2_g_a2236380', 'p2_g_4d13fb5a', 'p2_g_2fbe48dc', 'p2_g_7e25f57a', 'p2_g_e84a5159', 'p2_g_609eb8eb', 'p2_g_230aec35', 'p2_g_52b219ac', 'p2_g_34ed8946', 'p2_un_contrato', 'p2_ventana_horaria');

update catalogo_reglas set activa = false, updated_at = now()
 where etapa = 1 and es_checklist and activa;

notify pgrst, 'reload schema';
