insert into catalogo_reglas (codigo, titulo, enunciado, capa, tipo, fase, setup, es_checklist, orden, evidencia, bloquea_go, aplica_si, plan_reglas, origen, plan_tipo, plan_bloque, campo, estado, activa, etapa) values
  ('R-01', 'Analiza, marca zonas y ejecuta TODO sobre MNQ. Un solo grafico.', 'Analiza, marca zonas y ejecuta TODO sobre MNQ. Un solo grafico.', 'plan', 'dura', null, null, false, 1, null, false, 'siempre', array['R-01']::text[], 'plan_regla', null, 'Perímetro operativo', null, 'vigente', true, 2),
  ('R-02', 'Opera unicamente durante los 120 minutos siguientes a la apertura de la sesion americana.', 'Opera unicamente durante los 120 minutos siguientes a la apertura de la sesion americana.', 'plan', 'dura', null, null, false, 2, null, false, 'siempre', array['R-02']::text[], 'plan_regla', null, 'Perímetro operativo', null, 'vigente', true, 2),
  ('R-03', 'Opera con un grafico limpio: velas de 1 minuto y volumen, nada mas.', 'Opera con un grafico limpio: velas de 1 minuto y volumen, nada mas.', 'plan', 'dura', null, null, false, 3, null, false, 'siempre', array['R-03']::text[], 'plan_regla', null, 'Perímetro operativo', null, 'vigente', true, 2),
  ('R-04', 'Opera siempre 1 contrato MNQ. El tamano no cambia por capital, racha ni conviccion.', 'Opera siempre 1 contrato MNQ. El tamano no cambia por capital, racha ni conviccion.', 'plan', 'dura', null, null, false, 4, null, false, 'siempre', array['R-04']::text[], 'plan_regla', null, 'Perímetro operativo', null, 'vigente', true, 2),
  ('R-05', 'Una corrida (= impulso) es la secuencia de velas que arranca cuando una vela supera el extremo de la anterior y termina en la primera vela que retrocede al menos 1 tick contra ella.', 'Una corrida (= impulso) es la secuencia de velas que arranca cuando una vela supera el extremo de la anterior y termina en la primera vela que retrocede al menos 1 tick contra ella.', 'plan', 'dura', null, null, false, 5, null, false, 'siempre', array['R-05']::text[], 'plan_regla', null, 'Estructura del precio', null, 'vigente', true, 2),
  ('R-06', 'El retroceso es la secuencia de velas que arranca en la vela que mata la corrida y termina cuando nace la siguiente corrida.', 'El retroceso es la secuencia de velas que arranca en la vela que mata la corrida y termina cuando nace la siguiente corrida.', 'plan', 'dura', null, null, false, 6, null, false, 'siempre', array['R-06']::text[], 'plan_regla', null, 'Estructura del precio', null, 'vigente', true, 2),
  ('R-07', 'La vela de las 08:31 declara la direccion inicial de la sesion con su propio cuerpo y es la vela origen.', 'La vela de las 08:31 declara la direccion inicial de la sesion con su propio cuerpo y es la vela origen.', 'plan', 'dura', null, null, false, 7, null, false, 'siempre', array['R-07']::text[], 'plan_regla', null, 'Estructura del precio', null, 'vigente', true, 2),
  ('R-08', 'Vela con maximo mayor y minimo menor sin corrida viva: pasa a ser la nueva vela origen y la direccion la da la siguiente.', 'Vela con maximo mayor y minimo menor sin corrida viva: pasa a ser la nueva vela origen y la direccion la da la siguiente.', 'plan', 'dura', null, null, false, 8, null, false, 'siempre', array['R-08']::text[], 'plan_regla', null, 'Estructura del precio', null, 'vigente', true, 2),
  ('R-09', 'Marca la zona sobre la vela designada, desde el borde de su cuerpo hasta el extremo de su mecha, y extiendela hacia la derecha.', 'Marca la zona sobre la vela designada, desde el borde de su cuerpo hasta el extremo de su mecha, y extiendela hacia la derecha.', 'plan', 'dura', null, null, false, 9, null, false, 'siempre', array['R-09']::text[], 'plan_regla', null, 'Zonas', null, 'vigente', true, 2),
  ('R-10', 'Estirar la zona, rompimiento con mecha sin consecucion. El precio rompe una zona con mecha —el cierre se queda dentro— y la consecucion no llega. La zona se extiende hasta la punta de esa mecha: si es una RESISTENCIA se estira solo por arriba; si es un SOPORTE, solo por abajo.', 'Estirar la zona, rompimiento con mecha sin consecucion. El precio rompe una zona con mecha —el cierre se queda dentro— y la consecucion no llega. La zona se extiende hasta la punta de esa mecha: si es una RESISTENCIA se estira solo por arriba; si es un SOPORTE, solo por abajo.', 'plan', 'dura', null, null, false, 10, null, false, 'siempre', array['R-10']::text[], 'plan_regla', null, 'Zonas', null, 'vigente', true, 2),
  ('R-11', 'Zona apendice, rompimiento con cuerpo sin consecucion. El precio rompe una zona CON CUERPO —el cierre queda fuera— y la consecucion no llega. La zona original no se toca y nace una SEGUNDA zona sobre la mecha de la vela de rompimiento: un borde es el borde del cuerpo de esa vela, el otro es la punta de su mecha.', 'Zona apendice, rompimiento con cuerpo sin consecucion. El precio rompe una zona CON CUERPO —el cierre queda fuera— y la consecucion no llega. La zona original no se toca y nace una SEGUNDA zona sobre la mecha de la vela de rompimiento: un borde es el borde del cuerpo de esa vela, el otro es la punta de su mecha.', 'plan', 'dura', null, null, false, 11, null, false, 'siempre', array['R-11']::text[], 'plan_regla', null, 'Zonas', null, 'vigente', true, 2),
  ('R-12', 'Marca una zona entre dos zonas solo si el movimiento que la genera queda entero dentro de la mitad en la que empezo.', 'Marca una zona entre dos zonas solo si el movimiento que la genera queda entero dentro de la mitad en la que empezo.', 'plan', 'dura', null, null, false, 12, null, false, 'siempre', array['R-12']::text[], 'plan_regla', null, 'Zonas', null, 'vigente', true, 2),
  ('R-13', 'Si la zona que ibas a marcar toca una existente, no marques una nueva: estira la existente.', 'Si la zona que ibas a marcar toca una existente, no marques una nueva: estira la existente.', 'plan', 'dura', null, null, false, 13, null, false, 'siempre', array['R-13']::text[], 'plan_regla', null, 'Zonas', null, 'vigente', true, 2),
  ('R-14', 'El plazo de 5 velas es un TOPE, no una espera obligatoria: si antes el mercado arma una estructura completa en sentido contrario al rompimiento, la geometria se resuelve en ese momento.', 'El plazo de 5 velas es un TOPE, no una espera obligatoria: si antes el mercado arma una estructura completa en sentido contrario al rompimiento, la geometria se resuelve en ese momento.', 'plan', 'dura', null, null, false, 14, null, false, 'siempre', array['R-14']::text[], 'plan_regla', null, 'Zonas', null, 'vigente', true, 2),
  ('R-15', 'En la ventana de premercado (19:00 hora Colombia del dia anterior hasta la apertura americana), marca zona sobre TODA vela cuyo volumen supere el umbral. Fuera de esa ventana la regla no aplica.', 'En la ventana de premercado (19:00 hora Colombia del dia anterior hasta la apertura americana), marca zona sobre TODA vela cuyo volumen supere el umbral. Fuera de esa ventana la regla no aplica.', 'plan', 'dura', null, null, false, 15, null, false, 'siempre', array['R-15']::text[], 'plan_regla', null, 'Zonas', null, 'vigente', true, 2),
  ('R-16', 'La zona de la corrida se marca al aparecer el retroceso; la del retroceso solo cuando el retroceso queda confirmado. Antes es solo una linea provisional.', 'La zona de la corrida se marca al aparecer el retroceso; la del retroceso solo cuando el retroceso queda confirmado. Antes es solo una linea provisional.', 'plan', 'dura', null, null, false, 16, null, false, 'siempre', array['R-16']::text[], 'plan_regla', null, 'Zonas', null, 'vigente', true, 2),
  ('R-17', 'Dentro de una banda entre dos zonas se marca como maximo una zona en toda la jornada, y es la del primer retroceso.', 'Dentro de una banda entre dos zonas se marca como maximo una zona en toda la jornada, y es la del primer retroceso.', 'plan', 'dura', null, null, false, 17, null, false, 'siempre', array['R-17']::text[], 'plan_regla', null, 'Zonas', null, 'vigente', true, 2),
  ('R-18', 'Salir de una zona o de una banda es rompimiento mas consecucion, no geometria.', 'Salir de una zona o de una banda es rompimiento mas consecucion, no geometria.', 'plan', 'dura', null, null, false, 18, null, false, 'siempre', array['R-18']::text[], 'plan_regla', null, 'Zonas', null, 'vigente', true, 2),
  ('R-19', 'Seis precisiones de dibujo de zonas.', 'Seis precisiones de dibujo de zonas.', 'plan', 'dura', null, null, false, 19, null, false, 'siempre', array['R-19']::text[], 'plan_regla', null, 'Zonas', null, 'vigente', true, 2),
  ('R-20', 'Rompimiento es superar el borde de la zona por al menos un tick; consecucion es superar por un tick el extremo de la vela de rompimiento. La consecucion que TRASPASA una zona no tiene plazo.', 'Rompimiento es superar el borde de la zona por al menos un tick; consecucion es superar por un tick el extremo de la vela de rompimiento. La consecucion que TRASPASA una zona no tiene plazo.', 'plan', 'dura', null, null, false, 20, null, false, 'siempre', array['R-20']::text[], 'plan_regla', null, 'Zonas', null, 'vigente', true, 2),
  ('R-21', 'Una zona deja de tener efecto cuando ha sido superada en las dos direcciones.', 'Una zona deja de tener efecto cuando ha sido superada en las dos direcciones.', 'plan', 'dura', null, null, false, 21, null, false, 'siempre', array['R-21']::text[], 'plan_regla', null, 'Zonas', null, 'vigente', true, 2),
  ('R-22', 'La vela que confirma un traspaso no abre a la vez el rompimiento del lado contrario.', 'La vela que confirma un traspaso no abre a la vez el rompimiento del lado contrario.', 'plan', 'dura', null, null, false, 22, null, false, 'siempre', array['R-22']::text[], 'plan_regla', null, 'Zonas', null, 'vigente', true, 2),
  ('R-23', 'Toma el primer setup valido cuya orden se llene.', 'Toma el primer setup valido cuya orden se llene.', 'plan', 'dura', null, null, false, 23, null, false, 'siempre', array['R-23']::text[], 'plan_regla', null, 'Setup y entrada', null, 'vigente', true, 2),
  ('R-24', 'Entra siempre con orden stop en reposo colocada al cierre de la vela de rompimiento.', 'Entra siempre con orden stop en reposo colocada al cierre de la vela de rompimiento.', 'plan', 'dura', null, null, false, 24, null, false, 'siempre', array['R-24']::text[], 'plan_regla', null, 'Setup y entrada', null, 'vigente', true, 2),
  ('R-25', 'Setup Continuacion: un IRI —corrida, retroceso, zona y rompimiento de esa zona— y su consecucion. La consecucion es la entrada.', 'Setup Continuacion: un IRI —corrida, retroceso, zona y rompimiento de esa zona— y su consecucion. La consecucion es la entrada.', 'plan', 'dura', null, null, false, 25, null, false, 'siempre', array['R-25']::text[], 'plan_regla', null, 'Setup y entrada', null, 'vigente', true, 2),
  ('R-26', 'Setup Reingreso: tras un rompimiento con consecucion que falla, el precio recupera la zona entera y se opera en sentido contrario.', 'Setup Reingreso: tras un rompimiento con consecucion que falla, el precio recupera la zona entera y se opera en sentido contrario.', 'plan', 'dura', null, null, false, 26, null, false, 'siempre', array['R-26']::text[], 'plan_regla', null, 'Setup y entrada', null, 'vigente', true, 2),
  ('R-27', 'La direccion de la vela de las 08:31 marca por donde empieza el dia pero no obliga a operar en ese sentido toda la sesion.', 'La direccion de la vela de las 08:31 marca por donde empieza el dia pero no obliga a operar en ese sentido toda la sesion.', 'plan', 'dura', null, null, false, 27, null, false, 'siempre', array['R-27']::text[], 'plan_regla', null, 'Setup y entrada', null, 'vigente', true, 2),
  ('R-40', 'Corrida fluida: solo se entra en el rompimiento de la zona de una corrida FLUIDA. La secuencia tiene que salir bien tres veces seguidas: corrida, retroceso que no se pasa, y corrida siguiente que rompe la zona.', 'Corrida fluida: solo se entra en el rompimiento de la zona de una corrida FLUIDA. La secuencia tiene que salir bien tres veces seguidas: corrida, retroceso que no se pasa, y corrida siguiente que rompe la zona.', 'plan', 'dura', null, null, false, 28, null, false, 'siempre', array['R-40']::text[], 'plan_regla', null, 'Setup y entrada', null, 'vigente', true, 2),
  ('R-41', 'Punto de referencia: el objetivo de un REINGRESO no puede pasar del nivel de referencia de un retroceso anterior que siga vivo. Solo aplica al reingreso.', 'Punto de referencia: el objetivo de un REINGRESO no puede pasar del nivel de referencia de un retroceso anterior que siga vivo. Solo aplica al reingreso.', 'plan', 'dura', null, null, false, 29, null, false, 'siempre', array['R-41']::text[], 'plan_regla', null, 'Setup y entrada', null, 'vigente', true, 2),
  ('R-28', 'Ejecuta como maximo una operacion por sesion.', 'Ejecuta como maximo una operacion por sesion.', 'plan', 'dura', null, null, false, 30, null, false, 'siempre', array['R-28']::text[], 'plan_regla', null, 'Riesgo, orden y gestión', null, 'vigente', true, 2),
  ('R-29', 'Manten la orden pendiente hasta que se llene, hasta que se agoten 5 velas sin consecucion, hasta que el precio vuelva al punto del stop, o hasta el fin de la ventana.', 'Manten la orden pendiente hasta que se llene, hasta que se agoten 5 velas sin consecucion, hasta que el precio vuelva al punto del stop, o hasta el fin de la ventana.', 'plan', 'dura', null, null, false, 31, null, false, 'siempre', array['R-29']::text[], 'plan_regla', null, 'Riesgo, orden y gestión', null, 'vigente', true, 2),
  ('R-30', 'Una operacion abierta se gestiona hasta stop o target, aunque termine la ventana operativa.', 'Una operacion abierta se gestiona hasta stop o target, aunque termine la ventana operativa.', 'plan', 'dura', null, null, false, 32, null, false, 'siempre', array['R-30']::text[], 'plan_regla', null, 'Riesgo, orden y gestión', null, 'vigente', true, 2),
  ('R-31', 'Ejecuta con la ATM K1 al valor de ATM_DEFECTO y ajusta stop y target a mano tras el llenado, en ese orden.', 'Ejecuta con la ATM K1 al valor de ATM_DEFECTO y ajusta stop y target a mano tras el llenado, en ese orden.', 'plan', 'dura', null, null, false, 33, null, false, 'siempre', array['R-31']::text[], 'plan_regla', null, 'Riesgo, orden y gestión', null, 'vigente', true, 2),
  ('R-32', 'Ancla la regla en el nivel de entrada, mide el stop hasta su referencia estructural y pon el target a esa misma distancia.', 'Ancla la regla en el nivel de entrada, mide el stop hasta su referencia estructural y pon el target a esa misma distancia.', 'plan', 'dura', null, null, false, 34, null, false, 'siempre', array['R-32']::text[], 'plan_regla', null, 'Riesgo, orden y gestión', null, 'vigente', true, 2),
